import type { Metadata } from "next";
import type { ReactNode } from "react";

import { SALES_ORIGIN } from "@/lib/seo";

/**
 * Set here rather than only at the root so that Open Graph image URLs, which
 * are generated by Next.js as paths, resolve against the storefront host. A
 * crawler fetching an image from a different origin than the page is a
 * needless extra hop and some unfurlers treat it as untrusted.
 */
export const metadata: Metadata = {
  metadataBase: new URL(SALES_ORIGIN),
};

export default function MoneyMasteryLayout({ children }: { children: ReactNode }) {
  return (
    <div className="sales-root min-h-screen font-sans">{children}</div>
  );
}